NUMBER exponent.
INPUT(base).
INPUT(exponent).
NUMBER result = 1.
LOOP (NUMBER i = 1 TILL i <= exponent, i++) {
    result *= base.
}
IF (result % 2 == 0) {
    DISPLAYNL("EVEN").
} ELSE {
    DISPLAYNL("ODD").
}

